var hyperSDKCallback = function (response) {
  try {
    var parsedData = JSON.parse(response);
    updateData(JSON.stringify(parsedData, null, 2))
    console.log("response hypersdkcallback func: ", parsedData)
    var event = parsedData["event"];
    switch (event) {
      case "show_loader": {
        // Show some loader here
        toggleLoader(true);
      }
      break;
    case "hide_loader": {
      // Hide Loader
      toggleLoader(false);
    }
    break;
    case "initiate_result": {
      // Get the payload
      toggleLoader(false);
      let payload = parsedData["payload"];
      console.log("initiate result: ", parsedData)
    }
    break;
    case "process_result": {
      // Get the payload
      toggleLoader(false);
      let payload = parsedData["payload"];
      console.log("process result: ", parsedData)
    }
    break;
    default:
      //Error handling
      toggleLoader(false);
      let payload = parsedData;
      break;
    }
  } catch (error) {
    //Error handling
    console.log(error);
  }
}


function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = Math.random() * 16 | 0,
      v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const newOrderId = () => {
  var result           = '';
  var characters       = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  var charactersLength = characters.length;
  for ( var i = 0; i < 10; i++ ) {
    result += characters.charAt(Math.floor(Math.random() * charactersLength));
  }
  return result;
}


function getOuterPayload() {
  return {
    "requestId": uuidv4(),
    "service": "in.juspay.hyperpay",
    "payload": {}
  }
}

